    // Generate link for download btn
    generateDownloadBtnUrl(magnificationId, slideIndex = 0) {
        // Get download btn element
        let downloadBtn = $('#' + magnificationId).find(
            '.irantheme-gallery-magnification-slider-topbar .irantheme-gallery-magnification-slider-topbar-action .irantheme-gallery-magnification-slider-action-download',
        );
        if (downloadBtn.length) {
            // Slide active holder
            let activeSlide;
            // Check slide index default value
            if (slideIndex != 0) {
                // if run when swiper init
                // Get all swiper slide
                activeSlide = $('#' + magnificationId).find(
                    '.irantheme-gallery-magnification-slider-figure .swiper-wrapper .irantheme-gallery-magnification-slider-figure-item',
                );
                // Loop on all swiper slide
                activeSlide.each(function (index, element) {
                    // Check slide index
                    if (
                        $(element).attr('data-slide-id') ==
                        parseInt(slideIndex) + 1
                    ) {
                        // Assign url of active slide to download btn
                        $(downloadBtn).attr(
                            'href',
                            $(element).attr('data-url'),
                        );
                    }
                });
                // else run when slide changing
            } else {
                // Get active swiper slide
                activeSlide = $('#' + magnificationId).find(
                    '.irantheme-gallery-magnification-slider-figure .swiper-wrapper .irantheme-gallery-magnification-slider-figure-item.swiper-slide-active',
                );
                // Assign url of active slide to download btn
                $(downloadBtn).attr('href', activeSlide.attr('data-url'));
            }
        }
    }

