    // Init gallery magnification swiper
    magnificationSliderInit(initialSlideData = 0, magnificationId) {
        let current = this;
        // Generate figure slider id
        let figureSlider =
            '#' +
            magnificationId +
            ' .irantheme-gallery-magnification-slider-figure.swiper';
        // Generate thumb slider id
        let thumbSlider =
            '#' +
            magnificationId +
            ' .irantheme-gallery-magnification-slider-thumb.swiper';
        // Gallery simple items (Init section swiper slider)
        var swiperGallerySimpleMagnificationThumb = new Swiper(thumbSlider, {
            modules: [Navigation, Pagination, Thumbs, Autoplay, FreeMode],
            slidesPerView: 2,
            spaceBetween: 1,
            centeredSlides: true,
            freeMode: true,
            watchSlidesProgress: true,
            initialSlide: initialSlideData,
            lazy: {
                enabled: true,
                loadOnTransitionStart: true, // Start loading ASAP
                loadPrevNext: true,
            },
            breakpoints: {
                // when window width is >= 320px
                320: {
                    slidesPerView: 3,
                    spaceBetween: 2,
                },
                // when window width is >= 480px
                575: {
                    slidesPerView: 5,
                    spaceBetween: 5,
                },
                // when window width is >= 640px
                767: {
                    slidesPerView: 7,
                    spaceBetween: 5,
                },
                991: {
                    slidesPerView: 10,
                    spaceBetween: 8,
                },
                1199: {
                    slidesPerView: 18,
                    spaceBetween: 8,
                },
            },
        });

        // Gallery simple items (Init section swiper slider)
        var swiperGallerySimpleMagnification = new Swiper(figureSlider, {
            modules: [Navigation, Pagination, Thumbs, Autoplay, FreeMode],
            spaceBetween: 10,
            navigation: {
                nextEl: '.swiper-button-next',
                prevEl: '.swiper-button-prev',
            },
            thumbs: {
                swiper: swiperGallerySimpleMagnificationThumb,
            },
            lazy: {
                enabled: true,
                loadOnTransitionStart: true, // Start loading ASAP
                loadPrevNext: true,
            },
            initialSlide: initialSlideData,
            on: {
                afterInit: function () {
                    // Generate url for download btn
                    current.generateDownloadBtnUrl(
                        magnificationId,
                        initialSlideData,
                    );
                    // Generate url for share btn
                    current.generateShareBtnUrl(
                        magnificationId,
                        initialSlideData,
                    );
                },
            },
        });

        swiperGallerySimpleMagnification.on('slideChange', function () {
            // Get magnification holder
            let magnificationHolder = $(
                swiperGallerySimpleMagnification['wrapperEl'],
            )
                .parent()
                .parent();
            // Get current page number holder
            let pageHolder = magnificationHolder.find(
                '.irantheme-gallery-magnification-slider-topbar-page-current',
            );
            // Assign current slide number to page number holder
            pageHolder.text(
                parseInt(swiperGallerySimpleMagnification['activeIndex']) + 1,
            );
        });

        swiperGallerySimpleMagnification.on(
            'slideChangeTransitionEnd',
            function () {
                // Generate url for download btn
                current.generateDownloadBtnUrl(magnificationId);
                // Generate url for share btn
                current.generateShareBtnUrl(magnificationId);
            },
        );
    }

