    initDownloadableFileDetails() {
        $(document).on('ready', function () {
            if ($('.irantheme-downloadable-product').length) {
                let $variationsForm = $('.variations_form');
                let $infoBox = $('#irantheme_download_info');

                function updateDownloadDetails(variation) {
                    if (!$infoBox.length) return;

                    // If the variation is not selected or not downloadable
                    if (!variation || !variation.is_downloadable) {
                        $infoBox.find('#file_version_number').text('');
                        $infoBox.find('#file_update_date').text('');
                        $infoBox.find('#file_release_date').text('');
                        $infoBox.find('.irantheme-file-details').hide();
                        return;
                    }

                    // Display and update values, if the value is empty, display '---'
                    $infoBox
                        .find('#file_version_number')
                        .text(variation.file_version_number || '---');
                    $infoBox
                        .find('#file_update_date')
                        .text(variation.file_update_date || '---');
                    $infoBox
                        .find('#file_release_date')
                        .text(variation.file_release_date || '---');

                    $infoBox.find('.irantheme-file-details').show();
                }

                // --- 1. User Interaction Management ---

                // When the user selects a variation
                $variationsForm.on(
                    'found_variation',
                    function (event, variation) {
                        updateDownloadDetails(variation);
                    },
                );

                // When clearing the selection
                $variationsForm.on('reset_image', function () {
                    updateDownloadDetails(null); // Sending Null for clearing and hiding
                });

                // --- 2. Managing the initial page load ---

                if ($variationsForm.length) {
                    let initialVariationId = $variationsForm
                        .find('input[name="variation_id"]')
                        .val();
                    let allVariationsData =
                        $variationsForm.data('product_variations');

                    if (initialVariationId && allVariationsData) {
                        // Finding the Default Variation Object
                        let initialVariation = allVariationsData.find(
                            function (v) {
                                return v.variation_id == initialVariationId;
                            },
                        );

                        if (initialVariation) {
                            // Run an update with default variation data
                            updateDownloadDetails(initialVariation);
                        }
                    } else {
                        // If the default variation is not selected, we make sure the box remains hidden.
                        $infoBox.find('.irantheme-file-details').hide();
                    }
                }
            }
        });
    }
